import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Backend y APIs — Servicios hechos para permanecer","description":"FastAPI, Gin, Laravel, .NET, Express — diseño y operación de servicios y APIs que sobreviven tráfico real.","frontmatter":{"title":"Backend y APIs — Servicios hechos para permanecer","description":"FastAPI, Gin, Laravel, .NET, Express — diseño y operación de servicios y APIs que sobreviven tráfico real."},"headers":[],"relativePath":"es/skills/backend/index.md","filePath":"es/skills/backend/index.md"}`),a={name:`es/skills/backend/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="backend-y-apis-—-servicios-hechos-para-permanecer" tabindex="-1">Backend y APIs — Servicios hechos para permanecer <a class="header-anchor" href="#backend-y-apis-—-servicios-hechos-para-permanecer" aria-label="Permalink to “Backend y APIs — Servicios hechos para permanecer”">​</a></h1><p>Mi filosofía de backend es aburrida a propósito: contratos claros, fallos explícitos, y servicios que se reinician solos sin drama. La parte emocionante es lo que los servicios permiten — infraestructura de IA gratuita, paneles que sirven a usuarios reales, puentes que convierten cuentas web en APIs.</p><h2 id="stacks-con-los-que-entrego" tabindex="-1">Stacks con los que entrego <a class="header-anchor" href="#stacks-con-los-que-entrego" aria-label="Permalink to “Stacks con los que entrego”">​</a></h2><table tabindex="0"><thead><tr><th>Stack</th><th>Punto dulce</th></tr></thead><tbody><tr><td>Python — FastAPI / Django</td><td>APIs, agentes, puentes async I/O (GhostBrain, Hermes).</td></tr><tr><td>Go — Gin / stdlib</td><td>Servicios y CLIs de binario único (NetPilot, OmniRouter).</td></tr><tr><td>PHP — Laravel</td><td>Productos completos con auth, colas y paneles admin.</td></tr><tr><td>C# — ASP.NET</td><td>Servicios de nivel empresarial y backends de escritorio.</td></tr><tr><td>Node — Express / Fastify</td><td>Workers de borde, pegamento en tiempo real, prototipos rápidos.</td></tr></tbody></table><h2 id="no-negociables" tabindex="-1">No negociables <a class="header-anchor" href="#no-negociables" aria-label="Permalink to “No negociables”">​</a></h2><ul><li><strong>Endpoint de salud</strong> en todo lo longevo — mi propia herramienta (<a href="/Usf/es/projects/netpilot/">NetPilot</a>) los monitorea.</li><li><strong>Degradación elegante</strong> — un upstream muerto debe degradar funciones, jamás derribar el proceso.</li><li><strong>Logs estructurados</strong> desde el día uno, porque depurar por vibras no escala más allá de las 2 AM.</li><li><strong>Tests de contrato</strong> para todo lo que otros sistemas dependen — incluidos los agentes.</li></ul><p>El patrón se repite en mis proyectos: los <a href="/Usf/es/projects/glm-free-api/">puentes free-api</a> lidiar con upstreams hostiles y limitados; <a href="/Usf/es/projects/taskflow-api/">TaskFlow API</a> con estado multiusuario; los <a href="/Usf/es/projects/omnirouter/">routers</a> con el fallo entre ellos. Mismos principios, distintos puntos de presión.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};